#include <Eigen/Dense>
#include <Eigen/Geometry>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <numeric>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

namespace {
constexpr double G=9.81, CX=0.014570, CY=0.082383, PI=3.14159265358979323846;
struct Row {std::string stage; uint64_t us=0; double dt=0; Eigen::Vector3d a=Eigen::Vector3d::Zero(),w=Eigen::Vector3d::Zero(),wf=Eigen::Vector3d::Zero(),fc_rate=Eigen::Vector3d::Zero(),af=Eigen::Vector3d::Zero(),vf=Eigen::Vector3d::Zero(); Eigen::Matrix3d Rf=Eigen::Matrix3d::Identity();};
struct StaticWin {size_t b=0,e=0; std::string stage; double t=0; Eigen::Vector3d ma=Eigen::Vector3d::Zero(),mw=Eigen::Vector3d::Zero(); double acc_std=0,gyro_std=0,prev_abs=0,prev_E=0,Ex=0,Ey=0,Ez=0;};
struct CvResult {std::string name; double rmse12=0,rmse21=0,mean=0; int p=0;};
struct Replay {double gyro_rms=0,gyro_max=0,ori_rms=0,ori_max=0,vel_rms=0,vel_max=0;};
struct AdaptRes {double final_ang=0,final_axy=0,endpoint_rms=0,endpoint_max=0;};
struct MatFit {Eigen::Matrix3d A=Eigen::Matrix3d::Identity(); Eigen::Vector3d b=Eigen::Vector3d::Zero(); double train=0,cv12=0,cv21=0;};

std::vector<std::string> split(const std::string&s){std::vector<std::string>v;std::stringstream q(s);std::string x;while(std::getline(q,x,','))v.push_back(x);return v;}
double D(const std::string&s){return s.empty()?0.0:std::stod(s);}
Eigen::Matrix3d expSO3(const Eigen::Vector3d&q){double a=q.norm();if(a<1e-12)return Eigen::Matrix3d::Identity();return Eigen::AngleAxisd(a,q/a).toRotationMatrix();}
Eigen::Matrix3d rpyXYZ(double r,double p,double y){r*=PI/180;p*=PI/180;y*=PI/180;return Eigen::AngleAxisd(r,Eigen::Vector3d::UnitX()).toRotationMatrix()*Eigen::AngleAxisd(p,Eigen::Vector3d::UnitY()).toRotationMatrix()*Eigen::AngleAxisd(y,Eigen::Vector3d::UnitZ()).toRotationMatrix();}
double angleDeg(const Eigen::Vector3d&a,const Eigen::Vector3d&b){double c=a.normalized().dot(b.normalized());c=std::max(-1.0,std::min(1.0,c));return std::acos(c)*180.0/PI;}
double rmse(const Eigen::VectorXd&a,const Eigen::VectorXd&b){if(a.size()==0)return 0;return std::sqrt((a-b).squaredNorm()/double(a.size()));}

std::vector<Row> load(const std::string&p){std::ifstream f(p);if(!f)throw std::runtime_error("cannot open "+p);std::string l;std::getline(f,l);auto h=split(l);std::map<std::string,int>c;for(int i=0;i<(int)h.size();++i)c[h[i]]=i;const char* need[]={"stage","imu_us","dt","flu_ax","flu_ay","flu_az","raw_gx","raw_gy","raw_gz","fixed_gx","fixed_gy","fixed_gz","fc_rollspeed","fc_pitchspeed","fc_yawspeed","fixed_R_roll","fixed_R_pitch","fixed_R_yaw","fixed_aw_x","fixed_aw_y","fixed_aw_z","fixed_vx","fixed_vy","fixed_vz"};for(auto n:need)if(!c.count(n))throw std::runtime_error(std::string("missing column: ")+n);std::vector<Row>v;while(std::getline(f,l)){if(l.empty())continue;auto x=split(l);if(x.size()<h.size())continue;Row z;z.stage=x[c["stage"]];z.us=std::stoull(x[c["imu_us"]]);z.dt=D(x[c["dt"]]);z.a={D(x[c["flu_ax"]]),D(x[c["flu_ay"]]),D(x[c["flu_az"]])};z.w={D(x[c["raw_gx"]]),D(x[c["raw_gy"]]),D(x[c["raw_gz"]])};z.wf={D(x[c["fixed_gx"]]),D(x[c["fixed_gy"]]),D(x[c["fixed_gz"]])};z.fc_rate={D(x[c["fc_rollspeed"]]),D(x[c["fc_pitchspeed"]]),D(x[c["fc_yawspeed"]])};z.Rf=rpyXYZ(D(x[c["fixed_R_roll"]]),D(x[c["fixed_R_pitch"]]),D(x[c["fixed_R_yaw"]]));z.af={D(x[c["fixed_aw_x"]]),D(x[c["fixed_aw_y"]]),D(x[c["fixed_aw_z"]])};z.vf={D(x[c["fixed_vx"]]),D(x[c["fixed_vy"]]),D(x[c["fixed_vz"]])};v.push_back(z);}return v;}
size_t postCal(const std::vector<Row>&v){size_t s=0;while(s<v.size()&&v[s].stage=="CALIB_STATIC")++s;return s;}
Eigen::Vector3d inferBA(const std::vector<Row>&v,size_t s){Eigen::Vector3d ba=Eigen::Vector3d::Zero();size_t n=0;for(size_t i=s;i<v.size()&&n<2000;++i){ba+=v[i].a-v[i].Rf.transpose()*(v[i].af-Eigen::Vector3d(0,0,G));++n;}return n?ba/double(n):ba;}

std::vector<bool> staticMask(const std::vector<Row>&v,size_t s,double rateThr=0.010,double accStdThr=0.160){const int H=100;std::vector<bool>m(v.size(),false);if(v.size()<s+2*H+1)return m;std::vector<Eigen::Vector3d>pa(v.size()+1,Eigen::Vector3d::Zero()),pa2(v.size()+1,Eigen::Vector3d::Zero());for(size_t i=s;i<v.size();++i){pa[i+1]=pa[i]+v[i].a;pa2[i+1]=pa2[i]+v[i].a.cwiseProduct(v[i].a);}for(size_t i=s+H;i+H<v.size();++i){size_t b=i-H,e=i+H;double n=double(e-b);Eigen::Vector3d ma=((pa[e]-pa[b])/n).eval();Eigen::Vector3d va=((pa2[e]-pa2[b])/n-ma.cwiseProduct(ma)).eval();double as=std::sqrt(std::max(0.0,va.sum()));if(v[i].fc_rate.norm()<rateThr&&as<accStdThr&&std::abs(ma.norm()-G)<0.30)m[i]=true;}return m;}
std::vector<StaticWin> makeWindows(const std::vector<Row>&v,size_t s,const std::vector<bool>&sm){std::vector<StaticWin>out;size_t i=s,prev_end=s;while(i<v.size()){while(i<v.size()&&!sm[i])++i;if(i>=v.size())break;size_t b=i;std::string st=v[i].stage;while(i<v.size()&&sm[i]&&v[i].stage==st)++i;size_t e=i;if(e-b<100)continue;StaticWin w;w.b=b;w.e=e;w.stage=st;w.t=(v[(b+e)/2].us-v[s].us)*1e-6;for(size_t k=b;k<e;++k){w.ma+=v[k].a;w.mw+=v[k].w;}w.ma/=double(e-b);w.mw/=double(e-b);double av=0,gv=0;for(size_t k=b;k<e;++k){av+=(v[k].a-w.ma).squaredNorm();gv+=(v[k].w-w.mw).squaredNorm();}w.acc_std=std::sqrt(av/double(e-b));w.gyro_std=std::sqrt(gv/double(e-b));for(size_t k=prev_end;k<b;++k){double dt=(v[k].dt>0&&v[k].dt<.03)?v[k].dt:0;double q=v[k].w.norm();w.prev_abs+=q*dt;w.prev_E+=v[k].w.squaredNorm()*dt;w.Ex+=v[k].w.x()*v[k].w.x()*dt;w.Ey+=v[k].w.y()*v[k].w.y()*dt;w.Ez+=v[k].w.z()*v[k].w.z()*dt;}prev_end=e;out.push_back(w);}return out;}

Replay replay(const std::vector<Row>&v,size_t s,const Eigen::Vector3d&ba){Replay z;if(s>=v.size())return z;Eigen::Matrix3d R=v[s].Rf;Eigen::Vector3d vel=v[s].vf;double sg=0,so=0,sv=0;size_t ng=0,no=0,nv=0;for(size_t i=s;i<v.size();++i){Eigen::Vector3d f=v[i].w;f.x()+=CX*f.z();f.y()+=CY*f.z();double eg=(f-v[i].wf).norm();sg+=eg*eg;z.gyro_max=std::max(z.gyro_max,eg);++ng;if(i>s){double dt=(v[i].dt>0&&v[i].dt<.03)?v[i].dt:0;if(dt)R=R*expSO3(f*dt);Eigen::Quaterniond q1(R),q2(v[i].Rf);double dot=std::abs(q1.dot(q2));dot=std::max(0.0,std::min(1.0,dot));double eo=2*std::acos(dot)*180/PI;so+=eo*eo;z.ori_max=std::max(z.ori_max,eo);++no;Eigen::Vector3d aw=R*(v[i].a-ba)+Eigen::Vector3d(0,0,G);if(dt)vel+=aw*dt;double ev=(vel-v[i].vf).norm();sv+=ev*ev;z.vel_max=std::max(z.vel_max,ev);++nv;}}z.gyro_rms=std::sqrt(sg/std::max<size_t>(1,ng));z.ori_rms=std::sqrt(so/std::max<size_t>(1,no));z.vel_rms=std::sqrt(sv/std::max<size_t>(1,nv));return z;}

Eigen::VectorXd fitRidge(const Eigen::MatrixXd&X,const Eigen::VectorXd&y,double lambda){Eigen::MatrixXd A=X.transpose()*X+lambda*Eigen::MatrixXd::Identity(X.cols(),X.cols());return A.ldlt().solve(X.transpose()*y);}
Eigen::VectorXd feature(const StaticWin&w,const std::vector<int>&ids){Eigen::Vector3d u=w.ma.normalized();std::vector<double>all={1.0,w.t,w.t*w.t,u.x(),u.y(),u.z(),w.mw.y(),w.mw.z(),w.prev_abs,w.prev_E,w.Ex,w.Ey,w.Ez,w.ma.norm()-G};Eigen::VectorXd x(ids.size());for(size_t i=0;i<ids.size();++i)x((int)i)=all.at(ids[i]);return x;}
CvResult cvModel(const std::vector<StaticWin>&ws,const std::vector<int>&ids,const std::string&name){CvResult r;r.name=name;r.p=(int)ids.size();if(ws.size()<8){r.rmse12=r.rmse21=r.mean=999;return r;}size_t mid=ws.size()/2;auto one=[&](size_t tb,size_t te,size_t vb,size_t ve){Eigen::MatrixXd X(te-tb,ids.size());Eigen::VectorXd y(te-tb);for(size_t i=tb;i<te;++i){X.row(i-tb)=feature(ws[i],ids).transpose();y(i-tb)=ws[i].mw.x();}Eigen::VectorXd b=fitRidge(X,y,1e-10);Eigen::MatrixXd V(ve-vb,ids.size());Eigen::VectorXd yy(ve-vb);for(size_t i=vb;i<ve;++i){V.row(i-vb)=feature(ws[i],ids).transpose();yy(i-vb)=ws[i].mw.x();}return rmse(V*b,yy);};r.rmse12=one(0,mid,mid,ws.size());r.rmse21=one(mid,ws.size(),0,mid);r.mean=.5*(r.rmse12+r.rmse21);return r;}
std::vector<CvResult> exhaustiveBiasModels(const std::vector<StaticWin>&ws){std::vector<std::string>names={"1","t","t2","ux","uy","uz","by","bz","prev_abs","prev_E","Ex","Ey","Ez","acc_norm_err"};std::vector<CvResult>out;const int N=13;for(int mask=0;mask<(1<<N);++mask){if(__builtin_popcount((unsigned)mask)>4)continue;std::vector<int>ids={0};std::string nm="1";for(int j=0;j<N;++j)if(mask&(1<<j)){ids.push_back(j+1);nm+="+"+names[j+1];}out.push_back(cvModel(ws,ids,nm));}std::sort(out.begin(),out.end(),[](const CvResult&a,const CvResult&b){return a.mean<b.mean;});return out;}

std::pair<Eigen::Matrix3d,Eigen::Vector3d> fitAffine3(const std::vector<Row>&v,size_t b,size_t e,bool fixedInput){std::vector<size_t>idx;for(size_t i=b;i<e;++i)if(v[i].fc_rate.norm()>0.03&&v[i].fc_rate.norm()<4.0)idx.push_back(i);if(idx.size()<50)return {Eigen::Matrix3d::Identity(),Eigen::Vector3d::Zero()};Eigen::MatrixXd X(idx.size(),4),Y(idx.size(),3);for(size_t n=0;n<idx.size();++n){size_t i=idx[n];Eigen::Vector3d w=fixedInput?v[i].wf:v[i].w;X.row(n)<<w.transpose(),1.0;Y.row(n)=v[i].fc_rate.transpose();}Eigen::MatrixXd B=(X.transpose()*X+1e-9*Eigen::MatrixXd::Identity(4,4)).ldlt().solve(X.transpose()*Y);Eigen::Matrix3d A=B.topRows(3).transpose();Eigen::Vector3d c=B.row(3).transpose();return {A,c};}
double evalAffine(const std::vector<Row>&v,size_t b,size_t e,const Eigen::Matrix3d&A,const Eigen::Vector3d&c,bool fixedInput){double ss=0;size_t n=0;for(size_t i=b;i<e;++i)if(v[i].fc_rate.norm()>0.03&&v[i].fc_rate.norm()<4.0){Eigen::Vector3d w=fixedInput?v[i].wf:v[i].w;Eigen::Vector3d er=A*w+c-v[i].fc_rate;ss+=er.squaredNorm();++n;}return n?std::sqrt(ss/double(n)):999;}
MatFit dynamicFit(const std::vector<Row>&v,size_t s,bool fixedInput){MatFit m;size_t mid=(s+v.size())/2;auto f=fitAffine3(v,s,v.size(),fixedInput);m.A=f.first;m.b=f.second;m.train=evalAffine(v,s,v.size(),m.A,m.b,fixedInput);auto f1=fitAffine3(v,s,mid,fixedInput),f2=fitAffine3(v,mid,v.size(),fixedInput);m.cv12=evalAffine(v,mid,v.size(),f1.first,f1.second,fixedInput);m.cv21=evalAffine(v,s,mid,f2.first,f2.second,fixedInput);return m;}

AdaptRes runAdaptiveX(const std::vector<Row>&v,size_t s,const Eigen::Vector3d&ba,const std::vector<bool>&sm,double tau){AdaptRes z;Eigen::Matrix3d R=v[s].Rf;double bx=0;std::vector<double>ep;std::string prev=v[s].stage;for(size_t i=s+1;i<v.size();++i){double dt=(v[i].dt>0&&v[i].dt<.03)?v[i].dt:0;Eigen::Vector3d w=v[i].w;w.x()-=bx;w.x()+=CX*w.z();w.y()+=CY*w.z();if(dt)R=R*expSO3(w*dt);if(sm[i]&&dt){double a=1-std::exp(-dt/tau);bx+=a*(v[i].w.x()-bx);}if(v[i].stage!=prev){size_t q=i-1,b0=q,n=0;Eigen::Vector3d ma=Eigen::Vector3d::Zero();while(b0>s&&v[b0-1].stage==prev&&sm[b0-1])--b0;for(size_t k=b0;k<=q;++k)if(sm[k]){ma+=v[k].a-ba;++n;}if(n>100){ma/=double(n);ep.push_back(angleDeg(R.transpose()*Eigen::Vector3d(0,0,-1),ma));}prev=v[i].stage;}}Eigen::Vector3d ma=Eigen::Vector3d::Zero();size_t n=0;for(size_t i=s;i<v.size();++i)if(sm[i]&&v[i].stage=="FINAL_STATIC"){ma+=v[i].a-ba;++n;}if(n){ma/=double(n);z.final_ang=angleDeg(R.transpose()*Eigen::Vector3d(0,0,-1),ma);z.final_axy=(R*ma+Eigen::Vector3d(0,0,G)).head<2>().norm();}double ss=0;for(double x:ep){ss+=x*x;z.endpoint_max=std::max(z.endpoint_max,x);}if(!ep.empty())z.endpoint_rms=std::sqrt(ss/ep.size());return z;}

std::string excitationReport(const std::vector<StaticWin>&ws){if(ws.size()<3)return "INSUFFICIENT";Eigen::MatrixXd U(ws.size(),3);for(size_t i=0;i<ws.size();++i)U.row(i)=ws[i].ma.normalized().transpose();Eigen::RowVector3d mu=U.colwise().mean();Eigen::MatrixXd Cn=U.rowwise()-mu;Eigen::Matrix3d C=Cn.transpose()*Cn/double(ws.size());Eigen::SelfAdjointEigenSolver<Eigen::Matrix3d>es(C);Eigen::Vector3d ev=es.eigenvalues();double ratio=ev(0)/std::max(1e-12,ev(2));std::ostringstream o;o<<std::fixed<<std::setprecision(6)<<"gravity-direction covariance eig=["<<ev.transpose()<<"] rank_ratio="<<ratio;if(ratio<0.02)o<<" -> FULL ACCEL 3x3 UNDEREXCITED";else o<<" -> accel orientation excitation acceptable";return o.str();}
}

int main(int argc,char**argv){std::string in=argc>1?argv[1]:"/home/vio/jtzero_imu_master_v44.csv";std::string out=argc>2?argv[2]:"/home/vio/jtzero_forensic_v46_report.txt";try{auto v=load(in);size_t s=postCal(v);if(s>=v.size())throw std::runtime_error("no post-calibration boundary");Eigen::Vector3d ba=inferBA(v,s);auto sm=staticMask(v,s);auto ws=makeWindows(v,s,sm);auto rep=replay(v,s,ba);auto models=exhaustiveBiasModels(ws);auto rawFit=dynamicFit(v,s,false);auto zxyFit=dynamicFit(v,s,true);std::vector<double>taus={0.25,0.5,1,2,5,10,20};std::vector<std::pair<double,AdaptRes>>ar;for(double t:taus)ar.push_back({t,runAdaptiveX(v,s,ba,sm,t)});double dt_sum=0,dt2=0,dtmax=0;size_t dtn=0,bad=0;for(size_t i=s;i<v.size();++i){double dt=v[i].dt;if(dt>0&&dt<.03){dt_sum+=dt;dt2+=dt*dt;dtmax=std::max(dtmax,dt);++dtn;}else if(dt!=0)++bad;}double dtm=dtn?dt_sum/dtn:0,dts=dtn?std::sqrt(std::max(0.0,dt2/dtn-dtm*dtm)):0;double an_mean=0,an_std=0;size_t an_n=0;for(auto&w:ws){double q=w.ma.norm();an_mean+=q;an_std+=q*q;++an_n;}if(an_n){an_mean/=an_n;an_std=std::sqrt(std::max(0.0,an_std/an_n-an_mean*an_mean));}
std::ostringstream o;o<<std::fixed<<std::setprecision(9);o<<"======================================================================\nJT-ZERO FORENSIC ENGINE v46 — ONE-BUILD MULTI-HYPOTHESIS REPORT\n======================================================================\ninput: "<<in<<"\nrows: "<<v.size()<<"\npost-cal boundary: "<<s<<" stage="<<v[s].stage<<"\ninferred BA: ["<<ba.transpose()<<"]\n\n[A] EXACT REPLAY GATE\nfixed gyro RMS/MAX: "<<rep.gyro_rms<<" / "<<rep.gyro_max<<" rad/s\norientation RMS/MAX: "<<rep.ori_rms<<" / "<<rep.ori_max<<" deg\nvelocity RMS/MAX: "<<rep.vel_rms<<" / "<<rep.vel_max<<" m/s\ngate: "<<((rep.ori_max<1e-3&&rep.vel_max<1e-5)?"PASS":"FAIL")<<"\n\n[B] TIMING\nmean dt="<<dtm<<" std="<<dts<<" max="<<dtmax<<" bad="<<bad<<"\n\n[C] STATIC WINDOWS\ncount="<<ws.size()<<" selected_samples="<<std::count(sm.begin()+s,sm.end(),true)<<" accel_norm_mean="<<an_mean<<" accel_norm_std_between_windows="<<an_std<<"\n"<<excitationReport(ws)<<"\n";for(size_t i=0;i<ws.size();++i){auto&w=ws[i];o<<i<<" "<<w.stage<<" t="<<w.t<<" n="<<(w.e-w.b)<<" a_norm="<<w.ma.norm()<<" gmean=["<<w.mw.transpose()<<"] gstd="<<w.gyro_std<<" prevE=["<<w.Ex<<","<<w.Ey<<","<<w.Ez<<"]\n";}o<<"\n[D] EXHAUSTIVE CAUSAL BG_X FEATURE SEARCH\nfeatures: 1,t,t2,ux,uy,uz,by,bz,prev_abs,prev_E,Ex,Ey,Ez,acc_norm_err\nTop 15 by two-way cross-validation RMSE:\n";for(size_t i=0;i<std::min<size_t>(15,models.size());++i)o<<i+1<<" "<<models[i].name<<" p="<<models[i].p<<" cv12="<<models[i].rmse12<<" cv21="<<models[i].rmse21<<" mean="<<models[i].mean<<"\n";o<<"\n[E] CAUSAL ADAPTIVE BG_X GRID (independent FC-rate static guard)\n";for(auto&x:ar)o<<"tau="<<x.first<<" final_gravity="<<x.second.final_ang<<" final_axy="<<x.second.final_axy<<" endpoint_rms="<<x.second.endpoint_rms<<" endpoint_max="<<x.second.endpoint_max<<"\n";o<<"\n[F] DYNAMIC 3x3 GYRO->FC-RATE AFFINE CHECK\nRAW train_rms="<<rawFit.train<<" cv12="<<rawFit.cv12<<" cv21="<<rawFit.cv21<<"\nA_raw=\n"<<rawFit.A<<"\nb_raw=["<<rawFit.b.transpose()<<"]\nZXY train_rms="<<zxyFit.train<<" cv12="<<zxyFit.cv12<<" cv21="<<zxyFit.cv21<<"\nA_zxy=\n"<<zxyFit.A<<"\nb_zxy=["<<zxyFit.b.transpose()<<"]\nInterpretation: FC rates are an auxiliary reference, not absolute ground truth. A near-identity transferable A after ZXY demotes missing full 3x3 gyro calibration; large transferable off-diagonals strengthen it.\n\n[G] PROJECT-WIDE CONSISTENCY RULES\nv37: GTSAM/optimizer cannot be primary if independent SO(3) reproduces runaway.\nv38: gyro-propagated attitude is primary path; ACC_RP strongly reduced residual.\nv39: dt/midpoint/static startup bias do not explain original yaw catastrophe.\nv42: Z->XY correction is independently validated and MUST remain a baseline branch.\nv43: Z->XY sharply reduced live runaway but left residual.\nv45.1: offline replay must pass before any model is trusted.\nv45.2/45.3: causal X-bias adaptation is a confirmed practical correction candidate, not yet a physical explanation.\n\n[H] DECISION LOGIC\n1. If replay gate FAILS: stop; analyzer semantics are wrong.\n2. If top BG_X feature models transfer both directions and beat adaptive scale, prefer the simplest causal physical model.\n3. If exhaustive feature models are unstable but adaptive BG_X is stable, use adaptive BG_X as the engineering fix and keep physical-cause investigation separate.\n4. If dynamic 3x3 A has stable non-identity terms in both CV directions, add those terms only after independent validation; do not erase v42 ZXY.\n5. If accel excitation is underdetermined, do NOT fit full accel 3x3 from this run.\n6. Prefer a production change only when it improves endpoint gravity, final static axy, and cross-validation simultaneously.\n\n[OUTPUT FOR NEXT MESSAGE]\nSend this entire report once. No rebuild should be needed for any hypothesis represented by the feature bank above.\n";std::ofstream f(out);f<<o.str();std::cout<<o.str()<<"\nReport: "<<out<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"[FATAL] "<<e.what()<<"\n";return 1;}}
